-- public.hod_needing(p_world uuid, p_cx integer, p_cy integer, p_range integer, p_holding text, p_keeper uuid)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.hod_needing(p_world uuid, p_cx integer, p_cy integer, p_range integer, p_holding text, p_keeper uuid DEFAULT NULL::uuid)
 RETURNS TABLE(kind text, level integer, dir text, x integer, y integer, ref bigint, n integer, item text)
 LANGUAGE sql
 STABLE
AS $function$
  select w.kind, w.level, w.dir, w.x, w.y, w.ref, w.n, p_holding
  from hod_work(p_world, p_cx, p_cy, p_range) w
  where p_holding is not null and coalesce((w.needed->>p_holding)::int, 0) > 0
    and (p_keeper is null or hod_work_mine(p_world, p_keeper, w.dir, w.x, w.y))
    -- One it gets to: on the ground, or a storey up a staircase goes to (`hod_reached`).
    and hod_reached(p_world, w.kind, w.level, w.dir, w.x, w.y)
  order by (w.x - p_cx) ^ 2 + (w.y - p_cy) ^ 2,
           (w.needed->>p_holding)::double precision / greatest(1, coalesce((w.total->>p_holding)::double precision, 0)) desc,
           hod_rank(w.kind), w.level, w.dir collate "C", w.x, w.y
  limit 1
$function$
